import sympy as s
from pathlib import Path
e=s.symbols('e',integer=True,nonnegative=True)
def I(x,y):
 a,b=x;c,d=y
 return s.expand(-e*a*c+a*d+b*c)
def add(x,y):return tuple(s.expand(a+b) for a,b in zip(x,y))
def scale(k,x):return tuple(s.expand(k*a) for a in x)
H=(1,3*e+1);P=(4,12*e+3);A=(5,-1);B=(-1,12*e+5);D=(3,-6*e-3);K=(-2,-e-2)
c1=add(A,B);c2=I(A,B)
checks={'c1':c1,'c2':c2,'H2':I(H,H),'D2':I(D,D),'D_H':I(D,H),'D_P':I(D,P),'A_P':I(A,P),'B_P':I(B,P),'chiE':s.expand(2+(I(c1,c1)-I(c1,K))/2-c2)}
assert c1==scale(4,H)
assert c2==65*e+26
assert I(D,H)==0 and I(D,P)==-3
# H^2 of cross Hom groups vanishes by Serre duality: H0(K+-2D)=0.
# For aS+bf with a>=0, H0 is sum max(b-ie+1,0); if a<0 it is zero.
for sign in [-1,1]:
 div=add(K,scale(sign*2,D)); a,b=div
 if a<0: reason='negative fibre degree'
 else:
  assert b.subs(e,0)<0 and s.diff(b,e)<0
  reason='all pushdown line degrees negative'
 checks[f'K{sign:+}2D']=(div,reason)
print(checks)
# Explicit e=0 acyclicity and subbundle factorizations.
def hP1(n):return (max(n+1,0),max(-n-1,0))
def hprod(a,b):
 x,y=hP1(a);z,w=hP1(b)
 return (x*z,x*w+y*z,y*w)
assert hprod(5,-1)==hprod(-1,5)==(0,0,0)
sol=[]
for a in range(-20,25):
 for b in range(-20,25):
  if a*(4-b)+b*(4-a)==26:sol.append((a,b))
assert set(sol)=={(3,-7),(5,-1),(11,1),(1,11),(-1,5),(-7,3)}
print('e=0 possible everywhere sublines:',sol)
Path('workspace/agent2_invariants.txt').write_text(str(checks)+'\n'+str(sol))

